-- Q360 Health Underwriting & Pricing Core
-- Q360-MVP-ART-005 — DDL PostgreSQL V1
-- Version: 1.0 | Status: REVIEW
-- PostgreSQL baseline: 15+
-- Authority: physical schema baseline for Q360 V1.
-- IMPORTANT: commercial values and unresolved business fields remain outside this DDL.
-- OD-002 (currency/rounding), OD-003 (exact proposer/member fields), OD-005, OD-007 remain open.
--
-- Design principles:
--  * UUID identifiers generated by the application (no extension dependency required).
--  * tenant_id on business data.
--  * exact monetary arithmetic via NUMERIC, never floating point.
--  * immutable/versioned configuration and reproducible quote/pricing snapshots.
--  * optimistic locking via row_version where mutable aggregates require it.
--  * transactional outbox and idempotency records.
--  * explicit CHECK/UNIQUE/FK constraints.
--  * timestamps stored as timestamptz; business dates as date.
--
-- This file intentionally does NOT create application users, grants, RLS policies,
-- partitions, RabbitMQ topology, seed tariff values, or production secrets.
-- Those require environment/security decisions and/or later controlled artefacts.

BEGIN;

CREATE SCHEMA IF NOT EXISTS q360;

-- ============================================================
-- 1. TENANCY / AUDIT
-- ============================================================

CREATE TABLE q360.tenant (
    id                  uuid PRIMARY KEY,
    code                varchar(50) NOT NULL,
    name                varchar(200) NOT NULL,
    status              varchar(20) NOT NULL DEFAULT 'ACTIVE',
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    row_version         bigint NOT NULL DEFAULT 0,
    CONSTRAINT uq_tenant_code UNIQUE (code),
    CONSTRAINT ck_tenant_status CHECK (status IN ('ACTIVE','SUSPENDED','INACTIVE')),
    CONSTRAINT ck_tenant_row_version CHECK (row_version >= 0)
);

CREATE TABLE q360.audit_event (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    actor_id            varchar(200),
    actor_type          varchar(30) NOT NULL DEFAULT 'USER',
    action              varchar(120) NOT NULL,
    entity_type         varchar(120) NOT NULL,
    entity_id           varchar(200),
    occurred_at         timestamptz NOT NULL DEFAULT now(),
    correlation_id      varchar(100),
    trace_id            varchar(100),
    source              varchar(100),
    metadata_json       jsonb NOT NULL DEFAULT '{}'::jsonb,
    CONSTRAINT ck_audit_actor_type CHECK (actor_type IN ('USER','SYSTEM','SERVICE')),
    CONSTRAINT ck_audit_metadata_object CHECK (jsonb_typeof(metadata_json) = 'object')
);
CREATE INDEX ix_audit_tenant_occurred ON q360.audit_event(tenant_id, occurred_at DESC);
CREATE INDEX ix_audit_entity ON q360.audit_event(tenant_id, entity_type, entity_id);
CREATE INDEX ix_audit_correlation ON q360.audit_event(correlation_id) WHERE correlation_id IS NOT NULL;

-- ============================================================
-- 2. PRODUCT / PLAN / BENEFIT
-- ============================================================

CREATE TABLE q360.product (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    code                varchar(60) NOT NULL,
    name                varchar(200) NOT NULL,
    description         text,
    status              varchar(20) NOT NULL DEFAULT 'DRAFT',
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    row_version         bigint NOT NULL DEFAULT 0,
    CONSTRAINT uq_product_code UNIQUE (tenant_id, code),
    CONSTRAINT ck_product_status CHECK (status IN ('DRAFT','ACTIVE','INACTIVE','ARCHIVED')),
    CONSTRAINT ck_product_row_version CHECK (row_version >= 0)
);

CREATE TABLE q360.product_version (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    product_id          uuid NOT NULL REFERENCES q360.product(id),
    version_no          integer NOT NULL,
    effective_from      date NOT NULL,
    effective_to        date,
    status              varchar(20) NOT NULL DEFAULT 'DRAFT',
    published_at        timestamptz,
    published_by        varchar(200),
    checksum            varchar(128),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    row_version         bigint NOT NULL DEFAULT 0,
    CONSTRAINT uq_product_version UNIQUE (tenant_id, product_id, version_no),
    CONSTRAINT ck_product_version_no CHECK (version_no > 0),
    CONSTRAINT ck_product_version_dates CHECK (effective_to IS NULL OR effective_to >= effective_from),
    CONSTRAINT ck_product_version_status CHECK (status IN ('DRAFT','PUBLISHED','RETIRED')),
    CONSTRAINT ck_product_version_publish CHECK (
        (status = 'PUBLISHED' AND published_at IS NOT NULL)
        OR status <> 'PUBLISHED'
    ),
    CONSTRAINT ck_product_version_row_version CHECK (row_version >= 0)
);
CREATE INDEX ix_product_version_effective ON q360.product_version(tenant_id, product_id, effective_from, effective_to);

CREATE TABLE q360.plan (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    product_version_id  uuid NOT NULL REFERENCES q360.product_version(id),
    code                varchar(60) NOT NULL,
    name                varchar(200) NOT NULL,
    description         text,
    status              varchar(20) NOT NULL DEFAULT 'ACTIVE',
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    row_version         bigint NOT NULL DEFAULT 0,
    CONSTRAINT uq_plan_code UNIQUE (tenant_id, product_version_id, code),
    CONSTRAINT ck_plan_status CHECK (status IN ('ACTIVE','INACTIVE')),
    CONSTRAINT ck_plan_row_version CHECK (row_version >= 0)
);

CREATE TABLE q360.benefit (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    code                varchar(60) NOT NULL,
    name                varchar(200) NOT NULL,
    benefit_type        varchar(60),
    description         text,
    status              varchar(20) NOT NULL DEFAULT 'ACTIVE',
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    row_version         bigint NOT NULL DEFAULT 0,
    CONSTRAINT uq_benefit_code UNIQUE (tenant_id, code),
    CONSTRAINT ck_benefit_status CHECK (status IN ('ACTIVE','INACTIVE')),
    CONSTRAINT ck_benefit_row_version CHECK (row_version >= 0)
);

CREATE TABLE q360.plan_benefit (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    plan_id             uuid NOT NULL REFERENCES q360.plan(id),
    benefit_id          uuid NOT NULL REFERENCES q360.benefit(id),
    configuration_json  jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_plan_benefit UNIQUE (tenant_id, plan_id, benefit_id),
    CONSTRAINT ck_plan_benefit_config_object CHECK (jsonb_typeof(configuration_json) = 'object')
);

-- ============================================================
-- 3. VERSIONED PRICING CONFIGURATION
-- ============================================================

CREATE TABLE q360.pricing_parameter_set (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    code                varchar(80) NOT NULL,
    version_no          integer NOT NULL,
    effective_from      date NOT NULL,
    effective_to        date,
    status              varchar(20) NOT NULL DEFAULT 'DRAFT',
    checksum            varchar(128),
    published_at        timestamptz,
    published_by        varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    row_version         bigint NOT NULL DEFAULT 0,
    CONSTRAINT uq_pricing_parameter_set UNIQUE (tenant_id, code, version_no),
    CONSTRAINT ck_pps_version CHECK (version_no > 0),
    CONSTRAINT ck_pps_dates CHECK (effective_to IS NULL OR effective_to >= effective_from),
    CONSTRAINT ck_pps_status CHECK (status IN ('DRAFT','PUBLISHED','RETIRED')),
    CONSTRAINT ck_pps_row_version CHECK (row_version >= 0)
);

CREATE TABLE q360.pricing_parameter (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    parameter_set_id    uuid NOT NULL REFERENCES q360.pricing_parameter_set(id),
    parameter_code      varchar(100) NOT NULL,
    value_type          varchar(20) NOT NULL,
    decimal_value       numeric(30,12),
    integer_value       bigint,
    boolean_value       boolean,
    text_value          text,
    json_value          jsonb,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_pricing_parameter UNIQUE (tenant_id, parameter_set_id, parameter_code),
    CONSTRAINT ck_pricing_parameter_type CHECK (value_type IN ('DECIMAL','INTEGER','BOOLEAN','TEXT','JSON')),
    CONSTRAINT ck_pricing_parameter_one_value CHECK (
        (value_type='DECIMAL' AND decimal_value IS NOT NULL AND integer_value IS NULL AND boolean_value IS NULL AND text_value IS NULL AND json_value IS NULL) OR
        (value_type='INTEGER' AND decimal_value IS NULL AND integer_value IS NOT NULL AND boolean_value IS NULL AND text_value IS NULL AND json_value IS NULL) OR
        (value_type='BOOLEAN' AND decimal_value IS NULL AND integer_value IS NULL AND boolean_value IS NOT NULL AND text_value IS NULL AND json_value IS NULL) OR
        (value_type='TEXT' AND decimal_value IS NULL AND integer_value IS NULL AND boolean_value IS NULL AND text_value IS NOT NULL AND json_value IS NULL) OR
        (value_type='JSON' AND decimal_value IS NULL AND integer_value IS NULL AND boolean_value IS NULL AND text_value IS NULL AND json_value IS NOT NULL)
    )
);

CREATE TABLE q360.rating_table (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    code                varchar(80) NOT NULL,
    name                varchar(200) NOT NULL,
    version_no          integer NOT NULL,
    effective_from      date NOT NULL,
    effective_to        date,
    status              varchar(20) NOT NULL DEFAULT 'DRAFT',
    currency_code       char(3),
    checksum            varchar(128),
    published_at        timestamptz,
    published_by        varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    row_version         bigint NOT NULL DEFAULT 0,
    CONSTRAINT uq_rating_table UNIQUE (tenant_id, code, version_no),
    CONSTRAINT ck_rating_version CHECK (version_no > 0),
    CONSTRAINT ck_rating_dates CHECK (effective_to IS NULL OR effective_to >= effective_from),
    CONSTRAINT ck_rating_status CHECK (status IN ('DRAFT','PUBLISHED','RETIRED')),
    CONSTRAINT ck_rating_currency CHECK (currency_code IS NULL OR currency_code ~ '^[A-Z]{3}$'),
    CONSTRAINT ck_rating_row_version CHECK (row_version >= 0)
);

CREATE TABLE q360.rating_factor (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    rating_table_id     uuid NOT NULL REFERENCES q360.rating_table(id),
    factor_code         varchar(100) NOT NULL,
    dimension_json      jsonb NOT NULL DEFAULT '{}'::jsonb,
    factor_value        numeric(30,12) NOT NULL,
    priority            integer NOT NULL DEFAULT 0,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ck_rating_factor_dimension CHECK (jsonb_typeof(dimension_json) = 'object')
);
CREATE INDEX ix_rating_factor_lookup ON q360.rating_factor(tenant_id, rating_table_id, factor_code, priority DESC);
CREATE INDEX ix_rating_factor_dimension_gin ON q360.rating_factor USING gin(dimension_json);

CREATE TABLE q360.rule_set (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    code                varchar(80) NOT NULL,
    name                varchar(200) NOT NULL,
    rule_domain         varchar(40) NOT NULL,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_rule_set_code UNIQUE (tenant_id, code),
    CONSTRAINT ck_rule_domain CHECK (rule_domain IN ('ELIGIBILITY','PRICING','WORKFLOW','VALIDATION'))
);

CREATE TABLE q360.rule_version (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    rule_set_id         uuid NOT NULL REFERENCES q360.rule_set(id),
    version_no          integer NOT NULL,
    effective_from      date NOT NULL,
    effective_to        date,
    status              varchar(20) NOT NULL DEFAULT 'DRAFT',
    artifact_type       varchar(30) NOT NULL DEFAULT 'DECISION_TABLE',
    artifact_ref        text,
    artifact_checksum   varchar(128),
    published_at        timestamptz,
    published_by        varchar(200),
    approved_by         varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    row_version         bigint NOT NULL DEFAULT 0,
    CONSTRAINT uq_rule_version UNIQUE (tenant_id, rule_set_id, version_no),
    CONSTRAINT ck_rule_version_no CHECK (version_no > 0),
    CONSTRAINT ck_rule_dates CHECK (effective_to IS NULL OR effective_to >= effective_from),
    CONSTRAINT ck_rule_status CHECK (status IN ('DRAFT','PUBLISHED','RETIRED')),
    CONSTRAINT ck_rule_artifact_type CHECK (artifact_type IN ('DRL','DECISION_TABLE','JSON','INTERNAL')),
    CONSTRAINT ck_rule_four_eyes CHECK (
        approved_by IS NULL OR published_by IS NULL OR approved_by <> published_by
    ),
    CONSTRAINT ck_rule_row_version CHECK (row_version >= 0)
);

-- ============================================================
-- 4. CLIENT / POPULATION
-- Exact business identity fields remain subject to OD-003.
-- Extensible attributes are isolated in attributes_json and must not
-- become an excuse to bypass later schema governance.
-- ============================================================

CREATE TABLE q360.proposer (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    proposer_type       varchar(20) NOT NULL,
    external_reference  varchar(100),
    display_name        varchar(250) NOT NULL,
    registration_number varchar(100),
    attributes_json     jsonb NOT NULL DEFAULT '{}'::jsonb,
    status              varchar(20) NOT NULL DEFAULT 'ACTIVE',
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    row_version         bigint NOT NULL DEFAULT 0,
    CONSTRAINT ck_proposer_type CHECK (proposer_type IN ('INDIVIDUAL','ORGANISATION')),
    CONSTRAINT ck_proposer_status CHECK (status IN ('ACTIVE','INACTIVE')),
    CONSTRAINT ck_proposer_attributes CHECK (jsonb_typeof(attributes_json) = 'object'),
    CONSTRAINT ck_proposer_row_version CHECK (row_version >= 0)
);
CREATE UNIQUE INDEX uq_proposer_external_ref ON q360.proposer(tenant_id, external_reference)
WHERE external_reference IS NOT NULL;

CREATE TABLE q360.insured_member (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    proposer_id         uuid NOT NULL REFERENCES q360.proposer(id),
    external_reference  varchar(100),
    relationship_code   varchar(40) NOT NULL,
    first_name          varchar(120),
    last_name           varchar(120),
    date_of_birth       date,
    sex_code            varchar(20),
    attributes_json     jsonb NOT NULL DEFAULT '{}'::jsonb,
    status              varchar(20) NOT NULL DEFAULT 'ACTIVE',
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    row_version         bigint NOT NULL DEFAULT 0,
    CONSTRAINT ck_member_status CHECK (status IN ('ACTIVE','INACTIVE')),
    CONSTRAINT ck_member_attributes CHECK (jsonb_typeof(attributes_json) = 'object'),
    CONSTRAINT ck_member_row_version CHECK (row_version >= 0)
);
CREATE UNIQUE INDEX uq_member_external_ref ON q360.insured_member(tenant_id, proposer_id, external_reference)
WHERE external_reference IS NOT NULL;
CREATE INDEX ix_member_proposer ON q360.insured_member(tenant_id, proposer_id);

CREATE TABLE q360.import_job (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    proposer_id         uuid REFERENCES q360.proposer(id),
    import_type         varchar(30) NOT NULL,
    original_filename   varchar(255),
    file_checksum       varchar(128),
    status              varchar(20) NOT NULL DEFAULT 'UPLOADED',
    total_rows          integer NOT NULL DEFAULT 0,
    valid_rows          integer NOT NULL DEFAULT 0,
    invalid_rows        integer NOT NULL DEFAULT 0,
    created_by          varchar(200) NOT NULL,
    created_at          timestamptz NOT NULL DEFAULT now(),
    completed_at        timestamptz,
    CONSTRAINT ck_import_type CHECK (import_type IN ('MEMBER_POPULATION')),
    CONSTRAINT ck_import_status CHECK (status IN ('UPLOADED','VALIDATING','VALIDATED','COMMITTING','COMPLETED','FAILED')),
    CONSTRAINT ck_import_counts CHECK (total_rows >= 0 AND valid_rows >= 0 AND invalid_rows >= 0)
);

CREATE TABLE q360.import_row_error (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    import_job_id       uuid NOT NULL REFERENCES q360.import_job(id) ON DELETE CASCADE,
    row_number          integer NOT NULL,
    field_name          varchar(120),
    error_code          varchar(80) NOT NULL,
    error_message       text NOT NULL,
    raw_value_masked    text,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ck_import_row_number CHECK (row_number > 0)
);
CREATE INDEX ix_import_error_job ON q360.import_row_error(tenant_id, import_job_id, row_number);

-- ============================================================
-- 5. ELIGIBILITY
-- ============================================================

CREATE TABLE q360.eligibility_evaluation (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    proposer_id         uuid REFERENCES q360.proposer(id),
    member_id           uuid REFERENCES q360.insured_member(id),
    product_version_id  uuid NOT NULL REFERENCES q360.product_version(id),
    plan_id             uuid NOT NULL REFERENCES q360.plan(id),
    rule_version_id     uuid REFERENCES q360.rule_version(id),
    decision            varchar(20) NOT NULL,
    input_snapshot_json jsonb NOT NULL,
    evidence_json       jsonb NOT NULL DEFAULT '[]'::jsonb,
    evaluated_at        timestamptz NOT NULL DEFAULT now(),
    correlation_id      varchar(100),
    CONSTRAINT ck_eligibility_decision CHECK (decision IN ('ELIGIBLE','WARNING','REFERRAL','HARD_STOP','CONFIG_ERROR')),
    CONSTRAINT ck_elig_input_object CHECK (jsonb_typeof(input_snapshot_json) = 'object'),
    CONSTRAINT ck_elig_evidence_array CHECK (jsonb_typeof(evidence_json) = 'array')
);
CREATE INDEX ix_eligibility_member ON q360.eligibility_evaluation(tenant_id, member_id, evaluated_at DESC);

-- ============================================================
-- 6. PRICING EXECUTION / EXPLAINABILITY
-- ============================================================

CREATE TABLE q360.pricing_run (
    id                      uuid PRIMARY KEY,
    tenant_id               uuid NOT NULL REFERENCES q360.tenant(id),
    product_version_id      uuid NOT NULL REFERENCES q360.product_version(id),
    plan_id                 uuid NOT NULL REFERENCES q360.plan(id),
    rating_table_id         uuid NOT NULL REFERENCES q360.rating_table(id),
    parameter_set_id        uuid NOT NULL REFERENCES q360.pricing_parameter_set(id),
    rule_version_id         uuid REFERENCES q360.rule_version(id),
    status                  varchar(20) NOT NULL DEFAULT 'REQUESTED',
    effective_date          date NOT NULL,
    currency_code           char(3) NOT NULL,
    rounding_policy_code    varchar(80) NOT NULL,
    rounding_policy_version integer NOT NULL,
    input_snapshot_json     jsonb NOT NULL,
    total_amount            numeric(30,8),
    started_at              timestamptz,
    completed_at            timestamptz,
    failure_code            varchar(100),
    failure_message_safe    text,
    correlation_id          varchar(100),
    created_at              timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ck_pricing_status CHECK (status IN ('REQUESTED','CALCULATING','CALCULATED','FAILED')),
    CONSTRAINT ck_pricing_currency CHECK (currency_code ~ '^[A-Z]{3}$'),
    CONSTRAINT ck_rounding_version CHECK (rounding_policy_version > 0),
    CONSTRAINT ck_pricing_input_object CHECK (jsonb_typeof(input_snapshot_json) = 'object'),
    CONSTRAINT ck_pricing_result_consistency CHECK (
        (status='CALCULATED' AND total_amount IS NOT NULL AND completed_at IS NOT NULL)
        OR status <> 'CALCULATED'
    ),
    CONSTRAINT ck_pricing_failure_consistency CHECK (
        (status='FAILED' AND failure_code IS NOT NULL)
        OR status <> 'FAILED'
    )
);
CREATE INDEX ix_pricing_run_tenant_created ON q360.pricing_run(tenant_id, created_at DESC);
CREATE INDEX ix_pricing_run_versions ON q360.pricing_run(tenant_id, product_version_id, rating_table_id, parameter_set_id);

CREATE TABLE q360.pricing_component (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    pricing_run_id      uuid NOT NULL REFERENCES q360.pricing_run(id) ON DELETE CASCADE,
    member_id           uuid REFERENCES q360.insured_member(id),
    component_order     integer NOT NULL,
    component_code      varchar(100) NOT NULL,
    component_type      varchar(30) NOT NULL,
    base_amount         numeric(30,8),
    factor_value        numeric(30,12),
    adjustment_amount   numeric(30,8),
    result_amount       numeric(30,8) NOT NULL,
    source_code         varchar(120),
    source_version      varchar(80),
    metadata_json       jsonb NOT NULL DEFAULT '{}'::jsonb,
    CONSTRAINT uq_pricing_component_order UNIQUE (tenant_id, pricing_run_id, component_order),
    CONSTRAINT ck_pricing_component_order CHECK (component_order >= 0),
    CONSTRAINT ck_pricing_component_type CHECK (component_type IN ('BASE','FACTOR','ADJUSTMENT','FEE','TAX','TOTAL','OTHER')),
    CONSTRAINT ck_pricing_component_metadata CHECK (jsonb_typeof(metadata_json) = 'object')
);
CREATE INDEX ix_pricing_component_run ON q360.pricing_component(tenant_id, pricing_run_id);

CREATE TABLE q360.pricing_trace (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    pricing_run_id      uuid NOT NULL REFERENCES q360.pricing_run(id) ON DELETE CASCADE,
    sequence_no         integer NOT NULL,
    step_code           varchar(100) NOT NULL,
    rule_code           varchar(120),
    input_json          jsonb,
    output_json         jsonb,
    message             text,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_pricing_trace_sequence UNIQUE (tenant_id, pricing_run_id, sequence_no),
    CONSTRAINT ck_pricing_trace_sequence CHECK (sequence_no >= 0)
);

CREATE TABLE q360.pricing_scenario (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    base_pricing_run_id uuid REFERENCES q360.pricing_run(id),
    name                varchar(200) NOT NULL,
    input_override_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    result_pricing_run_id uuid REFERENCES q360.pricing_run(id),
    created_by          varchar(200) NOT NULL,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ck_pricing_scenario_override CHECK (jsonb_typeof(input_override_json) = 'object')
);

-- ============================================================
-- 7. QUOTATION
-- ============================================================

CREATE TABLE q360.quote (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    quote_number        varchar(100),
    proposer_id         uuid NOT NULL REFERENCES q360.proposer(id),
    product_version_id  uuid NOT NULL REFERENCES q360.product_version(id),
    plan_id             uuid NOT NULL REFERENCES q360.plan(id),
    status              varchar(20) NOT NULL DEFAULT 'DRAFT',
    effective_date      date NOT NULL,
    valid_until         date,
    currency_code       char(3),
    latest_pricing_run_id uuid REFERENCES q360.pricing_run(id),
    submitted_by        varchar(200),
    submitted_at        timestamptz,
    approved_by         varchar(200),
    approved_at         timestamptz,
    rejected_by         varchar(200),
    rejected_at         timestamptz,
    cancellation_reason text,
    created_by          varchar(200) NOT NULL,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    row_version         bigint NOT NULL DEFAULT 0,
    CONSTRAINT ck_quote_status CHECK (status IN ('DRAFT','READY','IN_REVIEW','APPROVED','REJECTED','EXPIRED','CANCELLED')),
    CONSTRAINT ck_quote_dates CHECK (valid_until IS NULL OR valid_until >= effective_date),
    CONSTRAINT ck_quote_currency CHECK (currency_code IS NULL OR currency_code ~ '^[A-Z]{3}$'),
    CONSTRAINT ck_quote_four_eyes CHECK (approved_by IS NULL OR submitted_by IS NULL OR approved_by <> submitted_by),
    CONSTRAINT ck_quote_row_version CHECK (row_version >= 0)
);
CREATE UNIQUE INDEX uq_quote_number ON q360.quote(tenant_id, quote_number) WHERE quote_number IS NOT NULL;
CREATE INDEX ix_quote_proposer ON q360.quote(tenant_id, proposer_id, created_at DESC);
CREATE INDEX ix_quote_status ON q360.quote(tenant_id, status, updated_at DESC);

CREATE TABLE q360.quote_member (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    quote_id            uuid NOT NULL REFERENCES q360.quote(id) ON DELETE CASCADE,
    member_id           uuid NOT NULL REFERENCES q360.insured_member(id),
    status              varchar(20) NOT NULL DEFAULT 'INCLUDED',
    eligibility_evaluation_id uuid REFERENCES q360.eligibility_evaluation(id),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_quote_member UNIQUE (tenant_id, quote_id, member_id),
    CONSTRAINT ck_quote_member_status CHECK (status IN ('INCLUDED','EXCLUDED','REFERRAL'))
);

CREATE TABLE q360.quote_snapshot (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    quote_id            uuid NOT NULL REFERENCES q360.quote(id),
    snapshot_no         integer NOT NULL,
    snapshot_type       varchar(30) NOT NULL,
    pricing_run_id      uuid REFERENCES q360.pricing_run(id),
    product_version_id  uuid NOT NULL REFERENCES q360.product_version(id),
    plan_id             uuid NOT NULL REFERENCES q360.plan(id),
    snapshot_json       jsonb NOT NULL,
    checksum            varchar(128) NOT NULL,
    created_by          varchar(200) NOT NULL,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_quote_snapshot_no UNIQUE (tenant_id, quote_id, snapshot_no),
    CONSTRAINT ck_quote_snapshot_no CHECK (snapshot_no > 0),
    CONSTRAINT ck_quote_snapshot_type CHECK (snapshot_type IN ('PRICING','SUBMISSION','APPROVAL','DOCUMENT')),
    CONSTRAINT ck_quote_snapshot_json CHECK (jsonb_typeof(snapshot_json) = 'object')
);
CREATE INDEX ix_quote_snapshot_quote ON q360.quote_snapshot(tenant_id, quote_id, snapshot_no DESC);

CREATE TABLE q360.quote_state_history (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES q360.tenant(id),
    quote_id            uuid NOT NULL REFERENCES q360.quote(id),
    from_status         varchar(20),
    to_status           varchar(20) NOT NULL,
    reason_code         varchar(100),
    reason_text         text,
    changed_by          varchar(200) NOT NULL,
    changed_at          timestamptz NOT NULL DEFAULT now(),
    correlation_id      varchar(100),
    CONSTRAINT ck_quote_history_to CHECK (to_status IN ('DRAFT','READY','IN_REVIEW','APPROVED','REJECTED','EXPIRED','CANCELLED')),
    CONSTRAINT ck_quote_history_from CHECK (from_status IS NULL OR from_status IN ('DRAFT','READY','IN_REVIEW','APPROVED','REJECTED','EXPIRED','CANCELLED'))
);
CREATE INDEX ix_quote_history ON q360.quote_state_history(tenant_id, quote_id, changed_at);

